INSERT INTO item VALUES (1529,'Tome of Leadership and Influence +1','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','27,500 gp',NULL,'Craft Wondrous Item, miracle or wish','1,250 gp + 5,100 XP','5 lb','\n      <div topic=\"Tome of Leadership and Influence\" level=\"8\"><p><b>Tome of Leadership and Influence:</b> This ponderous book details suggestions for persuading and inspiring others, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, he gains an inherent bonus of from +1 to +5 (depending on the type of tome) to his Charisma score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1530,'Tome of Leadership and Influence +2','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','55,000 gp',NULL,'Craft Wondrous Item, miracle or wish','2,500 gp + 10,200 XP','5 lb','\n      <div topic=\"Tome of Leadership and Influence\" level=\"8\"><p><b>Tome of Leadership and Influence:</b> This ponderous book details suggestions for persuading and inspiring others, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, he gains an inherent bonus of from +1 to +5 (depending on the type of tome) to his Charisma score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1531,'Tome of Leadership and Influence +3','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','82,500 gp',NULL,'Craft Wondrous Item, miracle or wish','3,750 gp + 15,300 XP','5 lb','\n      <div topic=\"Tome of Leadership and Influence\" level=\"8\"><p><b>Tome of Leadership and Influence:</b> This ponderous book details suggestions for persuading and inspiring others, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, he gains an inherent bonus of from +1 to +5 (depending on the type of tome) to his Charisma score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
