INSERT INTO item VALUES (1534,'Tome of Understanding +1','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','27,500 gp',NULL,'Craft Wondrous Item, miracle or wish','1,250 gp + 5,100 XP','5 lb','\n      <div topic=\"Tome of Understanding\" level=\"8\"><p><b>Tome of Understanding:</b> This thick book contains tips for improving instinct and perception, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, she gains an inherent bonus of from +1 to +5 (depending on the type of tome) to her Wisdom score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1535,'Tome of Understanding +2','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','55,000 gp',NULL,'Craft Wondrous Item, miracle or wish','2,500 gp + 10,200 XP','5 lb','\n      <div topic=\"Tome of Understanding\" level=\"8\"><p><b>Tome of Understanding:</b> This thick book contains tips for improving instinct and perception, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, she gains an inherent bonus of from +1 to +5 (depending on the type of tome) to her Wisdom score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1536,'Tome of Understanding +3','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','82,500 gp',NULL,'Craft Wondrous Item, miracle or wish','3,750 gp + 15,300 XP','5 lb','\n      <div topic=\"Tome of Understanding\" level=\"8\"><p><b>Tome of Understanding:</b> This thick book contains tips for improving instinct and perception, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, she gains an inherent bonus of from +1 to +5 (depending on the type of tome) to her Wisdom score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1537,'Tome of Understanding +4','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','110,000 gp',NULL,'Craft Wondrous Item, miracle or wish','5,000 gp + 20,400 XP','5 lb','\n      <div topic=\"Tome of Understanding\" level=\"8\"><p><b>Tome of Understanding:</b> This thick book contains tips for improving instinct and perception, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, she gains an inherent bonus of from +1 to +5 (depending on the type of tome) to her Wisdom score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1538,'Tome of Understanding +5','Wondrous',NULL,'No','Strong evocation (if miracle is used)','17','137,500 gp',NULL,'Craft Wondrous Item, miracle or wish','6,250 gp + 25,500 XP','5 lb','\n      <div topic=\"Tome of Understanding\" level=\"8\"><p><b>Tome of Understanding:</b> This thick book contains tips for improving instinct and perception, but entwined within the words is a powerful magical effect. If anyone reads this book, which takes a total of 48 hours over a minimum of six days, she gains an inherent bonus of from +1 to +5 (depending on the type of tome) to her Wisdom score. Once the book is read, the magic disappears from the pages and it becomes a normal book.</p><p>Strong evocation (if <i>miracle</i> is used); CL 17th; Craft Wondrous Item, <i>miracle</i> or <i>wish</i>; Price 27,500 gp (+1), 55,000 gp (+2), 82,500 gp (+3), 110,000 gp (+4), 137,500 gp (+5); Cost 1,250 gp + 5,100 XP (+1), 2,500 gp + 10,200 XP (+2), 3,750 gp + 15,300 XP (+3), 5,000 gp + 20,400 XP (+4), 6,250 gp + 25,500 XP (+5); Weight 5 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1539,'Unguent of Timelessness','Wondrous',NULL,'No','Faint transmutation','3','150 gp',NULL,'Craft Wondrous Item',NULL,NULL,'\n      <div topic=\"Unguent of Timelessness\" level=\"8\"><p><b>Unguent of Timelessness:</b> When applied to any matter that was once alive this ointment allows that substance to resist the passage of time. Each year of actual time affects the substance as if only a day had passed. The coated object gains a +1 resistance bonus on all saving throws. The unguent never wears off, although it can be magically removed (by dispelling the effect, for instance). One flask contains enough material to coat eight Medium or smaller objects. A Large object counts as two Medium objects, and a Huge object counts as two Large objects.</p><p>Faint transmutation; CL 3rd; <i>Prerequisite:</i> Craft Wondrous Item; Price 150 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1540,'Universal Solvent','Wondrous',NULL,'No','Strong transmutation','20','50 gp',NULL,'Craft Wondrous Item, disintegrate',NULL,NULL,'\n      <div topic=\"Universal Solvent\" level=\"8\"><p><b>Universal Solvent:</b> This substance has the unique property of being able to dissolve <i>sovereign glue</i> and tanglefoot bags. Applying the solvent is a standard action.</p><p>Strong transmutation; CL 20th; Craft Wondrous Item, <i>disintegrate</i>; Price 50 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1541,'Vest of Escape','Wondrous',NULL,'No','Faint conjuration and transmutation','4','5,200 gp',NULL,'Craft Wondrous Item, knock, grease',NULL,NULL,'\n      <div topic=\"Vest of Escape\" level=\"8\"><p><b>Vest of Escape:</b> Hidden within secret pockets of this simple silk vest are lockpicks that provide a +4 competence bonus on Open Lock checks. The vest also grants its wearer a +6 competence bonus on Escape Artist checks.</p><p>Faint conjuration and transmutation; CL 4th; Craft Wondrous Item, <i>knock</i>,  <i>grease</i>; Price 5,200 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1542,'Vestment, Druid\'s','Wondrous',NULL,'No','Moderate transmutation','10','10,000 gp',NULL,'Craft Wondrous Item, polymorph or wild shape ability',NULL,NULL,'\n      <div topic=\"Vestment, Druid\'s\" level=\"8\"><p><b>Vestment, Druid\'s:</b> This light garment is worn over normal clothing or armor. Most such vestments are green, embroidered with plant or animal motifs. When this item is worn by a character with the wild shape ability, the character can use that ability one additional time each day.</p><p>Moderate transmutation; CL 10th; Craft Wondrous Item, <i>polymorph</i> or wild shape ability; Price 10,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1543,'Well of Many Worlds','Wondrous',NULL,'No','Strong conjuration','17','82,000 gp',NULL,'Craft Wondrous Item, gate',NULL,NULL,'\n      <div topic=\"Well of Many Worlds\" level=\"8\"><p><b>Well of Many Worlds:</b> This strange, interdimensional device looks just like a <i>portable hole</i>. Anything placed within it is immediately cast to another world-a parallel world, another planet, or a different plane (chosen randomly). If the well is moved, the random factor again comes into play. It can be picked up, folded, or rolled, just as a <i>portable hole</i> can be. Objects from the world the well touches can come through the opening just as easily as from the initiating place. (It is a two-way portal.)</p><p>Strong conjuration; CL 17th; Craft Wondrous Item, <i>gate</i>; Price 82,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1544,'Wind Fan','Wondrous',NULL,'No','Faint evocation','5','5,500 gp',NULL,'Craft Wondrous Item, gust of wind',NULL,NULL,'\n      <div topic=\"Wind Fan\" level=\"8\"><p><b>Wind Fan:</b> A <i>wind fan</i> appears to be nothing more than a wood and papyrus or cloth instrument with which to create a cooling breeze. By uttering the command word, its possessor causes the fan to generate air movement duplicating a <i>gust of wind</i> spell. The fan can be used once per day with no risk. If it is used more frequently, there is a 20% cumulative chance per usage during that day that the device tears into useless, nonmagical tatters.</p><p>Faint evocation; CL 5th; Craft Wondrous Item, <i>gust of wind</i>; Price 5,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1545,'Wings of Flying','Wondrous',NULL,'No','Moderate transmutation','10','54,000 gp',NULL,'Craft Wondrous Item, fly',NULL,'2 lb','\n      <div topic=\"Wings of Flying\" level=\"8\"><p><b>Wings of Flying:</b> A pair of these wings might appear to be nothing more than a plain cloak of old, black cloth, or they could be as elegant as a long cape of blue feathers. When the wearer speaks the command word, the cloak turns into a pair of bat or bird wings that empower her to fly with a speed of 60 feet (good maneuverability).</p><p>Moderate transmutation; CL 10th; Craft Wondrous Item, <i>fly</i>; Price 54,000 gp; Weight 2 lb.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsV');
INSERT INTO item VALUES (1546,'Amulet of Inescapable Location','Cursed',NULL,'No','Moderate abjuration','10','1,000 gp',NULL,'Create Wondrous Item, bestow curse',NULL,NULL,'\n      <div topic=\"Amulet of Inescapable Location\" level=\"8\"><p><b>Amulet of Inescapable Location:</b> This device is typically worn on a chain or as a brooch. It appears, to magical analysis, to prevent location, scrying or detection or influence by <i>detect thoughts</i> or telepathy. It seems to be an <i>amulet of proof against detection and location</i>. Actually, the amulet gives the wearer a -10 penalty on all saves against divination spells.</p><p>Moderate abjuration; CL 10th; Create Wondrous Item, <i>bestow curse</i>; Price 1,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1547,'Armor of Arrow Attraction','Cursed',NULL,'No','Strong abjuration','16','9,000 gp',NULL,'Craft Magic Arms and Armor, bestow curse',NULL,NULL,'\n      <div topic=\"Armor of Arrow Attraction\" level=\"8\"><p><b>Armor of Arrow Attraction:</b> Magical analysis indicates that this armor is a normal suit of <i>+3 full plate</i>. However, the armor is cursed. It works normally with regard to melee attacks but actually serves to attract ranged weapons. The wearer takes a -15 penalty to AC against any attack by a ranged weapon. The true nature of the armor does not reveal itself until the character is fired upon in earnest.</p><p>Strong abjuration; CL 16th; Craft Magic Arms and Armor, <i>bestow curse</i>; Price 9,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1548,'Armor of Rage','Cursed',NULL,'No','Strong necromancy','16','1,600 gp',NULL,'Craft Magic Arms and Armor, bestow curse',NULL,NULL,'\n      <div topic=\"Armor of Rage\" level=\"8\"><p><b>Armor of Rage:</b> This armor is similar in appearance to <i>armor of command</i> and functions as a suit of <i>+1 full plate</i>. However, when it is worn, the armor causes the character to take a -4 penalty to Charisma. All unfriendly characters within 300 feet have a +1 morale bonus on attack rolls against her. The effect is not noticeable to the wearer or those affected. (In other words, the wearer does not immediately notice that donning the armor is the cause of her problems, nor do foes understand the reason for the depth of their enmity.)</p><p>Strong necromancy; CL 16th; Craft Magic Arms and Armor, <i>bestow curse</i>; Price 1,600 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1549,'Bag of Devouring','Cursed',NULL,'No','Moderate conjuration','17','n/a',NULL,'In effect, this is a creature and cannot be created',NULL,NULL,'\n      <div topic=\"Bag of Devouring\" level=\"8\"><p><b>Bag of Devouring:</b> This bag appears to be an ordinary sack. Detection for magical properties makes it seem as if it were a <i>bag of holding</i>. The sack is, however, a lure used by an extradimensional creature-in fact, one of its feeding orifices.</p><p>Any substance of animal or vegetable nature is subject to \'swallowing\'\' if thrust within the bag. The <i>bag of devouring</i> is 90% likely to ignore any initial intrusion, but any time thereafter that it senses living flesh within (such as if someone reaches into the bag to pull something out), it is 60% likely to close around the offending member and attempt to draw the whole victim in. The bag has a +8 bonus on grapple checks made to pull someone in.</p><p>The bag can hold up to 30 cubic feet of matter. It acts as a <i>bag of holding type I</i>,  but each hour it has a 5% cumulative chance of swallowing the contents and then spitting the stuff out in some nonspace or on some other plane. Creatures drawn within are consumed in 1 round. The bag destroys the victim\'s body and prevents any form of raising or resurrection that requires part of the corpse. There is a 50% chance that a <i>wish</i>,  <i>miracle</i>,  or <i>true resurrection</i> spell can restore a devoured victim to life. Check once for each destroyed creature. If the check fails, the creature cannot be brought back to life by mortal magic.</p><p>Moderate conjuration; CL 17th; In effect, this is a creature and cannot be created; Price n/a.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1550,'Boots of Dancing','Cursed',NULL,'No','Strong enchantment','16','30,000 gp',NULL,'Create Wondrous Item, irresistible dance',NULL,NULL,'\n      <div topic=\"Boots of Dancing\" level=\"8\"><p><b>Boots of Dancing:</b> These boots initially appear and function as one of the other kinds of magic boots. But when the wearer is in (or fleeing from) melee combat, <i>Boots of dancing</i> impede movement, making him behave as if <i>irresistible dance</i> had been cast upon him. Only a <i>remove curse</i> spell enables the wearer to be rid of the boots once their true nature is revealed.</p><p>Strong enchantment; CL 16th; Create Wondrous Item, <i>irresistible dance</i>; Price 30,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1551,'Bracers of Defenselessness','Cursed',NULL,'No','Moderate conjuration','16','1,200 gp',NULL,'Create Wondrous Item, Mage armor, bestow curse',NULL,NULL,'\n      <div topic=\"Bracers of Defenselessness\" level=\"8\"><p><b>Bracers of Defenselessness:</b> These appear to be <i>bracers of armor +5</i> and actually serve as such until the wearer is attacked in anger by an enemy with a Challenge Rating equal to or greater than her level. At that moment and thereafter, the bracers cause a -5 penalty to AC. Once their curse is activated, <i>Bracers of defenselessness</i> can be removed only by means of a <i>remove curse</i> spell.</p><p>Moderate conjuration; CL 16th; Create Wondrous Item, <i>Mage armor</i>,  <i>bestow curse</i>; Price 1,200 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1552,'Broom of Animated Attack','Cursed',NULL,'No','Moderate transmutation','10','5,200 gp',NULL,'Create Wondrous Item, fly, animate objects',NULL,NULL,'\n      <div topic=\"Broom of Animated Attack\" level=\"8\"><p><b>Broom of Animated Attack:</b> This item is indistinguishable in appearance from a normal broom. It is identical to a <i>broom of flying</i> by all tests short of attempted use.</p><p>If a command is spoken, the broom does a loop-the-loop with its hopeful rider, dumping him on his head from 1d4+5 feet off the ground (no falling damage, since the fall is less than 10 feet). The broom then attacks the victim, swatting the face with the straw or twig end and beating him with the handle end.</p><p>The broom gets two attacks per round with each end (two swats with the straw and two with the handle, for a total of four attacks per round). It attacks with a +5 bonus on each attack roll. The straw end causes a victim to be blinded for 1 round when it hits. The handle deals 1d6 points of damage when it hits. The broom has AC 13, 18 hit points, and hardness 4.</p><p>Moderate transmutation; CL 10th; Create Wondrous Item, <i>fly</i>,  <i>animate objects</i>; Price 5,200 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1553,'Cloak of Poisonousness','Cursed',NULL,'No','Strong abjuration','15','62,000 gp',NULL,'Create Wondrous Item, poison, and limited wish or miracle',NULL,NULL,'\n      <div topic=\"Cloak of Poisonousness\" level=\"8\"><p><b>Cloak of Poisonousness:</b> This cloak is usually made of a woolen material, although it can be made of leather. A <i>detect poison</i> spell can reveal the presence of poison impregnated in the cloak\'s fabric. The garment can be handled without harm, but as soon as it is actually donned the wearer is killed instantly unless she succeeds on a DC 28 Fortitude save.</p><p>Once donned, a <i>Cloak of poisonousness</i> can be removed only with a <i>remove curse</i> spell; doing this destroys the magical property of the cloak. If a <i>neutralize poison</i> spell is then used, it is possible to revive the victim with a <i>raise dead</i> or <i>resurrection</i> spell, but not before.</p><p>Strong abjuration; CL 15th; Create Wondrous Item, <i>poison</i>,  and <i>limited wish</i> or <i>miracle</i>; Price 62,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1554,'Crystal Hypnosis Ball','Cursed',NULL,'No','Moderate divination','17','n/a',NULL,'In effect, this is a minor artifact and cannot be created',NULL,NULL,'\n      <div topic=\"Crystal Hypnosis Ball\" level=\"8\"><p><b>Crystal Hypnosis Ball:</b> This cursed item is indistinguishable from a normal <i>crystal ball</i>. However, anyone attempting to use the scrying device becomes fascinated for 1d6 minutes, and a telepathic <i>suggestion</i> is implanted in his mind (Will DC 19 negates).</p><p>The user of the device believes that the desired creature or scene was viewed, but actually he came under the influence of a powerful wizard, lich, or even some power or being from another plane. Each further use brings the <i>crystal hypnosis ball</i> gazer deeper under the influence of the controller, either as a servant or a tool. Note that throughout this time, the user remains unaware of his subjugation.</p><p>Moderate divination; CL 17th; In effect, this is a minor artifact and cannot be created; Price n/a.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1555,'Dust of Sneezing and Choking','Cursed',NULL,'No','Faint conjuration','7','2,400 gp',NULL,'Create Wondrous Item, poison',NULL,NULL,'\n      <div topic=\"Dust of Sneezing and Choking\" level=\"8\"><p><b>Dust of Sneezing and Choking:</b> This fine dust appears to be <i>dust of appearance</i>. If cast into the air, it causes those within a 20- foot spread to fall into fits of sneezing and coughing. Those failing a DC 15 Fortitude save take 2d6 points of Constitution damage immediately. In addition, those failing a second DC 15 Fortitude save 1 minute later are dealt 1d6 points of Constitution damage. Those who succeed on either saving throw are nonetheless disabled by choking (treat as stunned) for 5d4 rounds.</p><p>Faint conjuration; CL 7th; Create Wondrous Item, <i>poison</i>; Price 2,400 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1556,'Flask of Curses','Cursed',NULL,'No','Moderate conjuration','7','2,100 gp',NULL,'Create Wondrous Item, bestow curse',NULL,NULL,'\n      <div topic=\"Flask of Curses\" level=\"8\"><p><b>Flask of Curses:</b> This item looks like an ordinary beaker, bottle, container, decanter, flask, or jug. It may contain a liquid, or it may emit smoke. When the flask is first unstoppered, all within 30 feet must make a DC 17 Will save or be cursed, taking a -2 penalty on attack rolls, saving throws, and skill checks until a <i>remove curse</i> spell is cast upon them.</p><p>Moderate conjuration; CL 7th; Create Wondrous Item, <i>bestow curse</i>; Price 2,100 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1557,'Gauntlets of Fumbling','Cursed',NULL,'No','Moderate transmutation','7','1,300 gp',NULL,'Create Wondrous Item, bestow curse',NULL,NULL,'\n      <div topic=\"Gauntlets of Fumbling\" level=\"8\"><p><b>Gauntlets of Fumbling:</b> These gauntlets may be of supple leather or heavy protective material suitable for use with armor. In the former instance, they appear to be <i>gloves of Dexterity</i>. In the latter case, they appear to be <i>gauntlets of ogre power</i>. The gauntlets perform according to every test as if they were <i>gloves of Dexterity</i> or <i>gauntlets of ogre power</i> until the wearer finds herself under attack or in a life-and-death situation. At that time, the curse is activated. The wearer becomes fumble-fingered, with a 50% chance each round of dropping anything held in either hand. The gauntlets also lower Dexterity by 2 points. Once the curse is activated, the gloves can be removed only by means of a <i>remove curse</i> spell, a <i>wish</i>,  or a <i>miracle</i>.</p><p>Moderate transmutation; CL 7th; Create Wondrous Item, <i>bestow curse</i>; Price 1,300 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1558,'Helm of Opposite Alignment','Cursed',NULL,'No','Strong transmutation','12','4,000 gp',NULL,'Create Wondrous Item, creator must be 12th level',NULL,'3 lb','\n      <div topic=\"Helm of Opposite Alignment\" level=\"8\"><p><b>Helm of Opposite Alignment:</b> This metal hat looks like a typical helmet. When placed upon the head, however, its curse immediately takes effect (Will DC 15 negates). On a failed save, the alignment of the wearer is radically altered to an alignment as different as possible from the former alignment-good to evil, chaotic to lawful, neutral to some extreme commitment (LE, LG, CE, or CG). Alteration in alignment is mental as well as moral, and the individual changed by the magic thoroughly enjoys his new outlook. A character who succeeds on his save can continue to wear the helmet without suffering the effect of the curse, but if he takes it off and later puts it on again, another save is required. The curse only works once; that is, a character whose alignment has been changed cannot change it again by donning the helmet a second time.</p><p>Only a <i>wish</i> or a <i>miracle</i> can restore former alignment, and the affected individual does not make any attempt to return to the former alignment. (In fact, he views the prospect with horror and avoids it in any way possible.) If a character of a class with an alignment requirement is affected, an <i>atonement</i> spell is needed as well if the curse is to be obliterated. When a <i>Helm of opposite alignment</i> has functioned once, it loses its magical properties.</p><p>Strong transmutation; CL 12th; Create Wondrous Item, creator must be 12th level; Price 4,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1559,'Incense of Obsession','Cursed',NULL,'No','Moderate enchantment','6','200 gp',NULL,'Create Wondrous Item, bestow curse',NULL,NULL,'\n      <div topic=\"Incense of Obsession\" level=\"8\"><p><b>Incense of Obsession:</b> These blocks of incense appear to be <i>incense of meditation</i>. If meditation and prayer are conducted while <i>incense of obsession</i> is burning nearby, its odor and smoke cause the user to become totally confident that her spell ability is superior, due to the magic incense. The user is determined to use her spells at every opportunity, even when not needed or when useless. The user remains obsessed with her abilities and spells until all have been used or cast, or until 24 hours have elapsed.</p><p>Moderate enchantment; CL 6th; Create Wondrous Item, <i>bestow curse</i>; Price 200 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1560,'Mace of Blood','Cursed',NULL,'No','Moderate abjuration','8','16,000 gp',NULL,'Craft Magic Arms and Armor, creator must be at least 9th level and chaotic evil',NULL,NULL,'\n      <div topic=\"Mace of Blood\" level=\"8\"><p><b>Mace of Blood:</b> This <i>+3 heavy mace</i> must be coated in blood every day, or its bonus fades away (until the mace is coated again). The character using this mace must make a DC 13 Will save every day it is within his possession or become chaotic evil.</p><p>Moderate abjuration; CL 8th; Craft Magic Arms and Armor, creator must be at least 9th level and chaotic evil; Price 16,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1561,'Medallion of Thought Projection','Cursed',NULL,'No','Faint divination','7','1,800 gp',NULL,'Create Wondrous Item, detect thoughts, ghost sound',NULL,NULL,'\n      <div topic=\"Medallion of Thought Projection\" level=\"8\"><p><b>Medallion of Thought Projection:</b> This device seems like a <i>medallion of thoughts</i>, even down to the range at which it functions, except that the thoughts overheard are muffled and distorted, requiring a DC 15 Will save to sort out. However, while the user thinks she is picking up the thoughts of others, all she is really hearing are figments created by the medallion itself. These illusory thoughts always seem plausible and thus can seriously mislead any who rely upon them. What\'s worse, unknown to her, the cursed medallion actually broadcasts her thoughts to creatures in the path of the beam, thus alerting them to her presence.</p><p>Faint divination; CL 7th; Create Wondrous Item, <i>detect thoughts</i>,  <i>ghost sound</i>; Price 1,800 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1562,'Necklace of Strangulation','Cursed',NULL,'No','Strong conjuration','18','60,000 gp',NULL,'Create Wondrous Item, slay living',NULL,NULL,'\n      <div topic=\"Necklace of Strangulation\" level=\"8\"><p><b>Necklace of Strangulation:</b> A <i>necklace of strangulation</i> appears to be a rare and wondrous piece of valuable jewelry and, short of the use of something as powerful as a <i>miracle</i> or a <i>wish</i>, can only be identified as a cursed item when placed around a character\'s neck. The necklace immediately constricts, dealing 6 points of damage per round. It cannot be removed by any means short of a <i>limited wish</i>,  <i>wish</i>,  or <i>miracle</i> and remains clasped around the victim\'s throat even after his death. Only when he has decayed to a dry skeleton (after approximately one month) does the necklace loosen, ready for another victim.</p><p>Strong conjuration; CL 18th; Create Wondrous Item, <i>slay living</i>; Price 60,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1563,'Net of Snaring','Cursed',NULL,'No','Moderate evocation','8','10,000 gp',NULL,'Craft Magic Arms and Armor, freedom of movement',NULL,NULL,'\n      <div topic=\"Net of Snaring\" level=\"8\"><p><b>Net of Snaring:</b> This net provides a +3 bonus on attack rolls but can only be used underwater, thus making it a somewhat useful item rather than what most would really call a cursed item. Underwater, it can be commanded to shoot forth up to 30 feet to trap a creature.</p><p>Moderate evocation; CL 8th; Craft Magic Arms and Armor, <i>freedom of movement</i>; Price 10,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1564,'Periapt of Foul Rotting','Cursed',NULL,'No','Faint abjuration','10','17,000 gp',NULL,'Create Wondrous Item, contagion',NULL,NULL,'\n      <div topic=\"Periapt of Foul Rotting\" level=\"8\"><p><b>Periapt of Foul Rotting:</b> This engraved gem appears to be of little value. If any character keeps the periapt in her possession for more than 24 hours, she contracts a terrible rotting affliction that permanently drains 1 point of Dexterity, Constitution, and Charisma every week. The periapt (and the affliction) can be removed only by application of a <i>remove curse</i> spell followed by a <i>cure disease</i> and then a <i>heal</i>,  <i>miracle</i>,  <i>limited wish</i>, or <i>wish</i> spell. The rotting can also be countered by crushing a <i>periapt of health</i> and sprinkling its dust upon the afflicted character (a full-round action), whereupon the periapt of foul rotting likewise crumbles to dust.</p><p>Faint abjuration; CL 10th; Create Wondrous Item, <i>contagion</i>; Price 17,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1565,'Potion of Poison','Cursed',NULL,'No','Moderate conjuration','12','5,000 gp',NULL,'Craft Wondrous Item, poison',NULL,NULL,'\n      <div topic=\"Potion of Poison\" level=\"8\"><p><b>Potion of Poison:</b> This potion has lost its once beneficial magical abilities and has become a potent poison. The imbiber must make a DC 16 Fortitude save or take 1d10 points of Constitution damage. A minute later he must save again (DC 16) or take 1d10 points of Constitution damage.</p><p>Moderate conjuration; CL 12th; Craft Wondrous Item, <i>poison</i>; Price 5,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1566,'Robe of Powerlessness','Cursed',NULL,'No','Moderate transmutation','13','5,500 gp',NULL,'Create Wondrous Item, bestow curse, permanency',NULL,NULL,'\n      <div topic=\"Robe of Powerlessness\" level=\"8\"><p><b>Robe of Powerlessness:</b> A <i>Robe of powerlessness</i> appears to be a magic robe of another sort. As soon as a character dons this garment, she takes a -10 penalty to Strength and Intelligence, forgetting spells and magic knowledge accordingly. The robe can be removed easily, but in order to restore mind and body, the character must receive a <i>remove curse</i> spell followed by <i>heal</i>.</p><p>Moderate transmutation; CL 13th; Create Wondrous Item, <i>bestow curse</i>,  <i>permanency</i>; Price 5,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1567,'Robe of Vermin','Cursed',NULL,'No','Moderate abjuration','13','16,500 gp',NULL,'Create Wondrous Item, summon swarm, creator must be at least 13th level',NULL,NULL,'\n      <div topic=\"Robe of Vermin\" level=\"8\"><p><b>Robe of Vermin:</b> The wearer notices nothing unusual when the robe is donned, other than that it offers great magical defense (as a <i>cloak of protection +4</i>). However, as soon as he is in a situation requiring concentration and action against hostile opponents, the true nature of the garment is revealed: The wearer immediately suffers a multitude of bites from the insects that magically infest the garment. He must cease all other activities in order to scratch, shift the robe, and generally show signs of the extreme discomfort caused by the bites and movement of these pests.</p><p>The wearer takes a -5 penalty on initiative checks and a -2 penalty on all attack rolls, saves, and skill checks. If he tries to cast a spell, he must make a Concentration check (DC 20 + spell level) or lose the spell.</p><p>Moderate abjuration; CL 13th; Create Wondrous Item, <i>summon swarm</i>,  creator must be at least 13th level; Price 16,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1568,'Ring of Clumsiness','Cursed',NULL,'No','Strong transmutation','15','500 gp',NULL,'Forge Ring, feather fall, bestow curse',NULL,NULL,'\n      <div topic=\"Ring of Clumsiness\" level=\"8\"><p><b>Ring of Clumsiness:</b> This ring operates exactly like a <i>ring of feather falling</i>. However, it also makes the wearer clumsy. She takes a -4 penalty to Dexterity and has a 20% chance of spell failure when trying to cast any arcane spell that has a somatic component. (This chance of spell failure stacks with other arcane spell failure chances.)</p><p>Strong transmutation; CL 15th; Forge Ring, <i>feather fall</i>,  <i>bestow curse</i>; Price 500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1569,'Scarab of Death','Cursed',NULL,'No','Strong abjuration','19','80,000 gp',NULL,'Create Wondrous Item, slay living',NULL,NULL,'\n      <div topic=\"Scarab of Death\" level=\"8\"><p><b>Scarab of Death:</b> This small pin appears to be any one of the various beneficial amulets, brooches, or scarabs. However, if it is held for more than 1 round or carried by a living creature for 1 minute, it changes into a horrible burrowing beetlelike creature. The thing tears through any leather or cloth, burrows into flesh, and reaches the victim\'s heart in 1 round, causing death. A DC 25 Reflex save allows the wearer to tear the scarab away before it burrows out of sight, but he still takes 3d6 points of damage. The beetle then returns to its scarab form. Placing the scarab in a container of wood, ceramic, bone, ivory, or metal prevents the monster from coming to life and allows for long-term storage of the item.</p><p>Strong abjuration; CL 19th; Create Wondrous Item, <i>slay living</i>; Price 80,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1570,'Spear, Cursed Backbiter','Cursed',NULL,'No','Moderate evocation','10','7,500 gp',NULL,'Craft Magic Arms and Armor, bestow curse',NULL,NULL,'\n      <div topic=\"Spear, Cursed Backbiter\" level=\"8\"><p><b>Spear, Cursed Backbiter:</b> This is a <i>+2 shortspear</i>,  but each time it is used in melee against a foe and the attack roll is a natural 1, it damages its wielder instead of her intended target. When the curse takes effect, the spear curls around to strike its wielder in the back, automatically dealing the damage to the wielder. The curse even functions when the spear is hurled, and in such a case the damage to the hurler is doubled.</p><p>Moderate evocation; CL 10th; Craft Magic Arms and Armor, <i>bestow curse</i>; Price 7,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1571,'Stone of Weight (Loadstone)','Cursed',NULL,'No','Strong evocation','15','1,500 gp',NULL,'Craft Magic Arms and Armor, bestow curse, and limited wish or miracle',NULL,NULL,'\n      <div topic=\"Stone of Weight\" level=\"8\"><p><b>Stone of Weight (Loadstone):</b> This stone appears to be a dark, smoothly polished stone. It reduces the possessor\'s base land speed to one-half of normal. Once picked up, the stone cannot be disposed of by any nonmagical means-if it is thrown away or smashed, it reappears somewhere on his person. If a <i>remove curse</i> spell is cast upon a <i>loadstone</i>,  the item may be discarded normally and no longer haunts the individual.</p><p>Faint transmutation; CL 5th; Create Wondrous Item, <i>slow</i>; Price 1,000 gp.</p><p><b>-2 Sword, Cursed:</b> This longsword performs well against targets in practice, but when used against an opponent in combat, it causes its wielder to take a -2 penalty on attack rolls.</p><p>All damage dealt is also reduced by 2 points, but never below a minimum of 1 point of damage on any successful hit. After one week in a character\'s possession, the sword always forces that character to employ it rather than another weapon. The sword\'s owner automatically draws it and fights with it even when she meant to draw or ready some other weapon. The sword can be gotten rid of only by means of <i>limited wish</i>, <i>wish</i>,  or <i>miracle</i>.</p><p>Strong evocation; CL 15th; Craft Magic Arms and Armor, <i>bestow curse</i>,  and <i>limited wish</i> or <i>miracle</i>; Price 1,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1572,'Sword, Berserking','Cursed',NULL,'No','Moderate evocation','8','17,500 gp',NULL,'Craft Magic Arms and Armor, rage, bestow curse',NULL,NULL,'\n      <div topic=\"Sword, Berserking\" level=\"8\"><p><b>Sword, Berserking:</b> This item appears to have the characteristics of a <i>+2 greatsword</i>. However, whenever the sword is used in battle, its wielder goes berserk (gaining all the benefits and drawbacks of the barbarian\'s rage ability). He attacks the nearest creature and continues to fight until unconscious or dead or until no living thing remains within 30 feet. Although many see this sword as a cursed object, others see it as a boon.</p><p>Moderate evocation; CL 8th; Craft Magic Arms and Armor, <i>rage</i>,  <i>bestow curse</i>; Price 17,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1573,'Vacuous Grimoire','Cursed',NULL,'No','Strong enchantment','20','6,000 gp',NULL,'Create Wondrous Item, feeblemind',NULL,NULL,'\n      <div topic=\"Vacuous Grimoire\" level=\"8\"><p><b>Vacuous Grimoire:</b> A book of this sort looks like a normal one on some mildly interesting topic. Any character who opens the work and reads so much as a single word therein must make two DC 15 Will saves. The first is to determine if the reader takes 1 point of permanent Intelligence drain. The second is to find out if the reader takes 2 points of permanent Wisdom drain. To destroy the book, a character must burn it while casting <i>remove curse</i>. If the grimoire is placed with other books, its appearance instantly alters to conform to the look of those other works.</p><p>Strong enchantment; CL 20th; Create Wondrous Item, <i>feeblemind</i>; Price 6,000 gp.</p><p/><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1574,'Book of Infinite Spells','Artifact','Minor Artifact','No','Strong (all schools)','18',NULL,NULL,NULL,NULL,'3 lb','\n      <div topic=\"Book of Infinite Spells\" level=\"8\"><p><b>Book of Infinite Spells:</b> This work bestows upon any character of any class the ability to use the spells within its pages. However, any character not already able to use spells gains one negative level for as long as the book is in her possession or while she uses its power. A <i>book of infinite spells</i> contains 1d8+22 pages. The nature of each page is determined by a dice roll: 01-50, arcane spell; 51-100, divine spell.</p><p>Determine the exact spell by using the tables for determining major scroll spells.</p><p>Once a page is turned, it can never be flipped back-paging through a <i>book of infinite spells</i> is a one-way trip. If the book is closed, it always opens again to the page it was on before the book was closed. When the last page is turned, the book vanishes.</p><p>Once per day the owner of the book can cast the spell to which the book is opened. If that spell happens to be one that is on the character\'s class spell list, she can cast it up to four times per day. The pages cannot be ripped out without destroying the book. Similarly, the spells cannot be cast as scroll spells, nor can they be copied into a spellbook-their magic is bound up permanently within the book itself.</p><p>The owner of the book need not have the book on her person in order to use its power. The book can be stored in a place of safety while the owner is adventuring and still allow its owner to cast spells by means of its power.</p><p>Each time a spell is cast, there is a chance that the energy connected with its use causes the page to magically turn despite all precautions. The owner knows this and may even benefit from the turning by gaining access to a new spell. The chance of a page turning depends on the spell the page contains and what sort of spellcaster the owner is.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Condition</b><br/></td>\n<td><b>Chance of Page Turning</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Caster employing a spell usable by own class and level<br/></td>\n<td>10%<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Caster employing a spell not usable by own class and level<br/></td>\n<td>20%<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Nonspellcaster employing divine spell<br/></td>\n<td>25%<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Nonspellcaster employing arcane spell<br/></td>\n<td>30%<br/></td>\n\n</tr>\n</table><p>Treat each spell use as if a scroll were being employed, for purposes of determining casting time, spell failure, and so on.</p><p>Strong (all schools); CL 18th; Weight 3 lb.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1575,'Deck of Many Things','Artifact','Minor Artifact','No','Strong (all schools)','20',NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Deck of Many Things\" level=\"8\"><p><b>Deck of Many Things:</b> A <i>deck of many things</i> (both beneficial and baneful) is usually found in a box or leather pouch. Each deck contains a number of cards or plaques made of ivory or vellum. Each is engraved with glyphs, characters, and sigils. As soon as one of these cards is drawn from the pack, its magic is bestowed upon the person who drew it, for better or worse.</p><p>The character with a <i>deck of many things</i> who wishes to draw a card must announce how many cards she will draw before she begins. Cards must be drawn within 1 hour of each other, and a character can never again draw from this deck any more cards than she has announced. If the character does not willingly draw her allotted number (or if she is somehow prevented from doing so), the cards flip out of the deck on their own. <i>Exception:</i> If the jester is drawn, the possessor of the deck may elect to draw two additional cards.</p><p>Each time a card is taken from the deck, it is replaced (making it possible to draw the same card twice) unless the draw is the jester or the fool, in which case the card is discarded from the pack. A <i>deck of many things</i> contains 22 cards. To simulate the magic cards, you may want to use tarot cards, as indicated in the second column of the accompanying table. If no tarot deck is available, substitute ordinary playing cards instead, as indicated in the third column. The effects of each card, summarized on the table, are fully described below.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"2\">\n<td colspan=\"4\"><b>Deck of Many Things</b><br/></td> \n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Plaque</b><br/></td>\n<td><b>Tarot Card</b><br/></td>\n<td><b>Playing Card</b><br/></td>\n<td><b>Summary of Effect</b><br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Balance<br/></td>\n<td>XI. Justice<br/></td>\n<td>Two of spades<br/></td>\n<td>Change alignment instantly.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Comet<br/></td>\n<td>Two of swords<br/></td>\n<td>Two of diamonds<br/></td>\n<td>Defeat the next monster you meet to gain one level.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Donjon<br/></td>\n<td>Four of swords<br/></td>\n<td>Ace of spades<br/></td>\n<td>You are <i>imprisoned</i>.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Euryale<br/></td>\n<td>Ten of swords<br/></td>\n<td>Queen of spades<br/></td>\n<td>-1 penalty on all saving throws henceforth.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>The Fates<br/></td>\n<td>Three of cups<br/></td>\n<td>Ace of hearts<br/></td>\n<td>Avoid any situation you choose . . . once.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Flames<br/></td>\n<td>XV. The Devil<br/></td>\n<td>Queen of clubs<br/></td>\n<td>Enmity between you and an outsider.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Fool<br/></td>\n<td>0. The Fool<br/></td>\n<td>Joker (with trademark)<br/></td>\n<td>Lose 10,000 experience points and you must draw again.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Gem<br/></td>\n<td>Seven of cups<br/></td>\n<td>Two of hearts<br/></td>\n<td>Gain your choice of twenty-five pieces of jewelry or fifty gems.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Idiot<br/></td>\n<td>Two of pentacles<br/></td>\n<td>Two of clubs<br/></td>\n<td>Lose Intelligence (permanent drain). You may draw again.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Jester<br/></td>\n<td>XII. The Hanged Man<br/></td>\n<td>Joker (without trademark)<br/></td>\n<td>Gain 10,000 XP or two more draws from the deck.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Key<br/></td>\n<td>V. The Hierophant<br/></td>\n<td>Queen of hearts<br/></td>\n<td>Gain a major magic weapon.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Knight<br/></td>\n<td>Page of swords<br/></td>\n<td>Jack of hearts<br/></td>\n<td>Gain the service of a 4th-level fighter.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Moon<br/></td>\n<td>XVIII. The Moon<br/></td>\n<td>Queen of diamonds<br/></td>\n<td>You are granted 1d4 wishes.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Rogue<br/></td>\n<td>Five of swords<br/></td>\n<td>Jack of spades<br/></td>\n<td>One of your friends turns against you.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Ruin<br/></td>\n<td>XVI. The Tower<br/></td>\n<td>King of spades<br/></td>\n<td>Immediately lose all wealth and real property.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Skull<br/></td>\n<td>XIII. Death<br/></td>\n<td>Jack of clubs<br/></td>\n<td>Defeat dread wraith or be forever destroyed.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Star<br/></td>\n<td>XVII. The Star<br/></td>\n<td>Jack of diamonds<br/></td>\n<td>Immediately gain a +2 inherent bonus to one ability score.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Sun<br/></td>\n<td>XIX. The Sun<br/></td>\n<td>King of diamonds<br/></td>\n<td>Gain beneficial medium wondrous item and 50,000 XP.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Talons<br/></td>\n<td>Queen of pentacles<br/></td>\n<td>Ace of clubs<br/></td>\n<td>All magic items you possess disappear permanently.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Throne<br/></td>\n<td>Four of staves<br/></td>\n<td>King of hearts<br/></td>\n<td>Gain a +6 bonus on Diplomacy checks plus a small keep.<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Vizier<br/></td>\n<td>IX. The Hermit<br/></td>\n<td>Ace of diamonds<br/></td>\n<td>Know the answer to your next dilemma.<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>The Void<br/></td>\n<td>Eight of swords<br/></td>\n<td>King of clubs<br/></td>\n<td>Body functions, but soul is trapped elsewhere.<br/></td>\n\n</tr>\n</table><p/><p><i>Balance:</i> The character must change to a radically different alignment. If the character fails to act according to the new alignment, she gains a negative level.</p><p><i>Comet:</i> The character must single-handedly defeat the next hostile monster or monsters encountered, or the benefit is lost. If successful, the character gains enough XP to attain the next experience level.</p><p><i>Donjon:</i> This card signifies imprisonment- either by the <i>imprisonment</i> spell or by some powerful being. All gear and spells are stripped from the victim in any case. Draw no more cards.</p><p><i>Euryale:</i> The medusalike visage of this card brings a curse that only the fates card or a deity can remove. The -1 penalty on all saving throws is otherwise permanent.</p><p><i>Fates:</i> This card enables the character to avoid even an instantaneous occurrence if so desired, for the fabric of reality is unraveled and respun. Note that it does not enable something to happen. It can only stop something from happening or reverse a past occurrence. The reversal is only for the character who drew the card; other party members may have to endure the situation.</p><p><i>Flames:</i> Hot anger, jealousy, and envy are but a few of the possible motivational forces for the enmity. The enmity of the outsider can\'t be ended until one of the parties has been slain. Determine the outsider randomly, and assume that it attacks the character (or plagues her life in some way) within 1d20 days.</p><p><i>Fool:</i> The payment of XP and the redraw are mandatory. This card is always discarded when drawn, unlike all others except the jester.</p><p><i>Gem:</i> This card indicates wealth. The jewelry is all gold set with gems, each piece worth 2,000 gp, the gems 1,000 gp value each.</p><p><i>Idiot:</i> This card causes the drain of 1d4+1 points of Intelligence immediately. The additional draw is optional.</p><p><i>Jester:</i> This card is always discarded when drawn, unlike all others except the fool. The redraws are optional.</p><p><i>Key:</i> The magic weapon granted must be one usable by the character. It suddenly appears out of nowhere in the character\'s hand.</p><p><i>Knight:</i> The fighter appears out of nowhere and serves loyally until death. He or she is of the same race (or kind) and gender as the character.</p><p><i>Moon:</i> This card sometimes bears the image of a moonstone gem with the appropriate number of <i>wishes</i> shown as gleams therein; sometimes it depicts a moon with its phase indicating the number of <i>wishes</i> (full = four; gibbous = three; half = two; quarter = one). These <i>wishes</i> are the same as those granted by the 9th-level wizard spell and must be used within a number of minutes equal to the number received.</p><p><i>Rogue:</i> When this card is drawn, one of the character\'s NPC friends (preferably a cohort) is totally alienated and forever after hostile. If the character has no cohorts, the enmity of some powerful personage (or community, or religious order) can be substituted. The hatred is secret until the time is ripe for it to be revealed with devastating effect.</p><p><i>Ruin:</i> As implied by its name, when this card is drawn, all nonmagical possessions of the drawer are lost.</p><p><i>Skull:</i> A dread wraith appears. Treat this creature as an unturnable undead. The character must fight it alone-if others help, they get dread wraiths to fight as well. If the character is slain, she is slain forever and cannot be revived, even with a <i>wish</i> or a <i>miracle</i>.</p><p><i>Star:</i> The 2 points are added to any ability the character chooses. They cannot be divided among two abilities.</p><p><i>Sun:</i> Roll for a medium wondrous item until a useful item is indicated.</p><p><i>Talons:</i> When this card is drawn, every magic item owned or possessed by the character is instantly and irrevocably gone.</p><p><i>Throne:</i> The character becomes a true leader in people\'s eyes. The castle gained appears in any open area she wishes (but the decision where to place it must be made within 1 hour).</p><p><i>Vizier:</i> This card empowers the character drawing it with the one-time ability to call upon a source of wisdom to solve any single problem or answer fully any question upon her request. The query or request must be made within one year. Whether the information gained can be successfully acted upon is another question entirely.</p><p><i>The Void:</i> This black card spells instant disaster. The character\'s body continues to function, as though comatose, but her psyche is trapped in a prison somewhere-in an object on a far plane or planet, possibly in the possession of an outsider. A <i>wish</i> or a <i>miracle</i> does not bring the character back, instead merely revealing the plane of entrapment. Draw no more cards.</p><p>Strong (all schools); CL 20th.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1576,'Hammer of Thunderbolts','Artifact','Minor Artifact','No','Strong evocation, necromancy, and transmutation','20',NULL,NULL,NULL,NULL,'15 lb','\n      <div topic=\"Hammer of Thunderbolts\" level=\"8\"><p><b>Hammer of Thunderbolts:</b> This <i>+3 Large returning warhammer</i> deals 4d6 points of damage on any hit. Further, if the wielder wears a <i>belt of giant Strength</i> and <i>gauntlets of ogre power</i> and he knows that the hammer is a <i>hammer of thunderbolts</i> (not just a <i>+3 warhammer</i>), the weapon can be used to full effect: It gains a total +5 enhancement bonus, allows all <i>belt</i> and <i>gauntlet</i> bonuses to stack (only when using this weapon), and strikes dead any giant upon whom it scores a hit (Fortitude DC 20 negates the death effect but not the damage).</p><p>When hurled, on a successful attack the hammer emits a great noise, like a clap of thunder, causing all creatures within 90 feet to be stunned for 1 round (Fortitude DC 15 negates). The hammer\'s range increment is 30 feet.</p><p>Strong evocation, necromancy, and transmutation; CL 20th; Weight 15 lb.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1577,'Philosopher\'s Stone','Artifact','Minor Artifact','No','Strong transmutation','20',NULL,NULL,NULL,NULL,'3 lb','\n      <div topic=\"Philosopher\'s Stone\" level=\"8\"><p><b>Philosopher\'s Stone:</b> This rare substance appears to be an ordinary, sooty piece of blackish rock. If the stone is broken open (break DC 20), a cavity is revealed at the stone\'s heart. This cavity is lined with a magical type of quicksilver that enables any arcane spellcaster to transmute base metals (iron and lead) into silver and gold. A single <i>philosopher\'s stone</i> can turn from up to 5,000 pounds of iron into silver, or up to 1,000 pounds of lead into gold. However, the quicksilver becomes unstable once the stone is opened and loses its potency within 24 hours, so all transmutations must take place within that period.</p><p>The quicksilver found in the center of the stone may also be put to another use. If mixed with any <i>cure</i> potion while the substance is still potent, it creates a special <i>oil of life</i> that acts as a <i>true resurrection</i> spell for any dead body it is sprinkled upon.</p><p>Strong transmutation; CL 20th; Weight 3 lb.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1578,'Sphere of Annihilation','Artifact','Minor Artifact','No','Strong transmutation','20',NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sphere of Annihilation\" level=\"8\"><p><b>Sphere of Annihilation:</b> A <i>sphere of annihilation</i> is a globe of absolute blackness, a ball of nothingness 2 feet in diameter. The object is actually a hole in the continuity of the multiverse. Any matter that comes in contact with a sphere is instantly sucked into the void, gone, and utterly destroyed. Only the direct intervention of a deity can restore an annihilated character.</p><p>A <i>sphere of annihilation</i> is static, resting in some spot as if it were a normal hole. It can be caused to move, however, by mental effort (think of this as a mundane form of telekinesis, too weak to move actual objects but a force to which the sphere, being weightless, is sensitive). A character\'s ability to gain control of a <i>sphere of annihilation</i> (or to keep controlling one) is based on the result of a control check against DC 30 (a move action). A control check is 1d20 + character level + character Int modifier. If the check succeeds, the character can move the sphere (perhaps to bring it into contact with an enemy) as a free action.</p><p>Control of a sphere can be established from as far away as 40 feet (the character need not approach too closely). Once control is established, it must be maintained by continuing to make control checks (all DC 30) each round. For as long as a character maintains control (does not fail a check) in subsequent rounds, he can control the sphere from a distance of 40 feet + 10 feet per character level. The sphere\'s speed in a round is 10 feet +5 feet for every 5 points by which the character\'s control check result in that round exceeded 30.</p><p>If a control check fails, the sphere slides 10 feet in the direction of the character attempting to move it.</p><p>If two or more creatures vie for control of a <i>sphere of annihilation</i>,  the rolls are opposed. If none are successful, the sphere slips toward the one who rolled lowest.</p><p>Should a <i>gate</i> spell be cast upon a <i>sphere of annihilation</i>, there is a 50% chance (01-50 on d%) that the spell destroys it, a 35% chance (51-85) that the spell does nothing, and a 15% chance (86-100) that a gap is torn in the spatial fabric, catapulting everything within a 180-foot radius into another plane. If a <i>rod of cancellation</i> touches a <i>sphere of annihilation</i>,</p><p>they negate each other in a tremendous explosion. Everything within a 60-foot radius takes 2d6x10 points of damage. <i>Dispel</i></p><p><i>magic</i> and <i>mage\'s disjunction</i> have no effect on a sphere.</p><p>See also <i>talisman of the sphere</i> (below).</p><p>Strong transmutation; CL 20th.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1579,'Staff of the Magi','Artifact','Minor Artifact','No','Strong (all schools)','20',NULL,NULL,NULL,NULL,'5 lb','\n      <div topic=\"Staff of the Magi\" level=\"8\"><p><b>Staff of the Magi:</b> A long wooden staff, shod in iron and inscribed with sigils and runes of all types, this potent artifact contains many spell powers and other functions. Some of its powers use charges, while others don\'t. The following powers do not use charges:</p><ul>\n <li> <i>Detect magic</i></li>\n <li> <i>Enlarge person (</i>Fortitude DC 15 negates)</li>\n <li> <i>Hold portal</i></li>\n <li> <i>Light</i></li>\n <li> <i>Mage armor</i></li>\n <li> <i>Mage hand</i></li>\n</ul><p>The following powers drain 1 charge per usage:</p><ul>\n <li> <i>Dispel magic</i></li>\n <li> <i>Fireball</i> (10d6 damage, Reflex DC 17 half )</li>\n <li> <i>ice storm</i></li>\n <li> <i>Invisibility</i></li>\n <li> <i>Knock</i></li>\n <li> <i>Lightning bolt</i> (10d6 damage, Reflex DC 17 half )</li>\n <li> <i>Passwall</i></li>\n <li> <i>Pyrotechnics</i> (Will or Fortitude DC 16 negates)</li>\n <li> <i>Wall of fire</i></li>\n <li> <i>Web</i></li>\n</ul><p>These powers drain 2 charges per usage:</p><ul>\n <li> <i>Monster summoning IX</i></li>\n <li> <i>Plane shift</i> (Will DC 21 negates)</li>\n <li> <i>Telekinesis</i> (400 lb. maximum weight; Will DC 19 negates)</li>\n</ul><p>A <i>staff of the magi</i> gives the wielder spell resistance 23. If this is willingly lowered, however, the staff can also be used to absorb arcane spell energy directed at its wielder, as a <i>rod of absorption</i> does. Unlike the rod, this staff converts spell levels into charges rather than retaining them as spell energy usable by a spellcaster. If the staff absorbs enough spell levels to exceed its limit of 50 charges, it explodes as if a retributive strike had been performed (see below). The wielder has no idea how many spell levels are cast at her, for the staff does not communicate this knowledge as a <i>rod of absorption</i> does. (Thus, absorbing spells can be risky.)</p><p><i>Retributive Strike:</i> A <i>staff of the magi</i> can be broken for a retributive strike. Such an act must be purposeful and declared by the wielder. All charges in the staff are released in a 30-foot spread. All within 10 feet of the broken staff take hit points of damage equal to 8 times the number of charges in the staff, those between 11 feet and 20 feet away take points equal to 6 times the number of charges, and those 21 feet to 30 feet distant take 4 times the number of charges. A DC 17 Reflex save reduces damage by half.</p><p>The character breaking the staff has a 50% chance (01-50 on d%) of traveling to another plane of existence, but if she does not (51-100), the explosive release of spell energy destroys her. Only specific items, including the <i>staff of the magi</i> and the <i>staff of power</i> are capable of a retributive strike.</p><p>Strong (all schools); CL 20th; Weight 5 lb.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1580,'Talisman of Pure Good','Artifact','Minor Artifact','No','Strong evocation [good]','18',NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Talisman of Pure Good\" level=\"8\"><p><b>Talisman of Pure Good:</b> A good (LG, NG, CG) divine spellcaster who possesses this item can cause a flaming crack to open at the feet of an evil (LE, NE, CE) divine spellcaster who is up to 100 feet away. The intended victim is swallowed up forever and sent hurtling to the center of the earth. The wielder of the talisman must be good, and if he is not exceptionally pure in thought and deed the evil character gains a DC 19 Reflex saving throw to leap away from the crack. Obviously, the target must be standing on solid ground for this item to function.</p><p>A <i>talisman of pure good</i> has 6 charges. If a neutral (LN, N, CN) divine spellcaster touches one of these stones, he takes 6d6 points of damage. If an evil divine spellcaster touches one, he takes 8d6 points of damage. All other characters are unaffected by the device.</p><p>Strong evocation [good]; CL 18th.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1581,'Talisman of the Sphere','Artifact','Minor Artifact','No','Strong transmutation','16',NULL,NULL,NULL,NULL,'1 lb','\n      <div topic=\"Talisman of the Sphere\" level=\"8\"><p><b>Talisman of the Sphere:</b> This small adamantine loop and handle are useless to those unable to cast arcane spells. Characters who cannot cast arcane spells take 5d6 points of damage merely from picking up and holding a talisman of this sort. However, when held by an arcane spellcaster who is concentrating on control of a <i>sphere of annihilation</i>,  a <i>talisman of the sphere</i> doubles the character\'s modifier on his control check (doubling both his Intelligence bonus and his character level for this purpose).</p><p>If the wielder of a talisman establishes control, he need check for maintaining control only every other round thereafter. If control is not established, the sphere moves toward him. Note that while many spells and effects of cancellation have no effect upon a <i>sphere of annihilation</i>,  the talisman\'s power of control can be suppressed or canceled.</p><p>Strong transmutation; CL 16th; Weight 1 lb.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1582,'Talisman of Reluctant Wishes','Artifact','Minor Artifact','No','Strong conjuration','20',NULL,NULL,NULL,NULL,'1 lb','\n      <div topic=\"Talisman of Reluctant Wishes\" level=\"8\"><p><b>Talisman of Reluctant Wishes:</b> A talisman of this sort appears the same as a <i>stone of controlling earth elementals</i>. Its powers are quite different, however, and dependent on the Charisma of the individual holding the talisman. Whenever a character touches a <i>talisman of reluctant wishes</i>,  he must make a DC 15 Charisma check.</p><p>If he fails, the device acts as a <i>stone of weight</i>. Discarding or destroying it results in 5d6 points of damage to the character and the disappearance of the talisman.</p><p>If he succeeds, the talisman remains with the character for 5d6 hours, or until a <i>wish</i> is made with it, whichever comes first. It then disappears.</p><p>If he rolls a natural 20, the character finds it impossible to be rid of the talisman for as many months as he has points of Charisma. In addition, the artifact grants him one <i>wish</i> for every 6 points of the character\'s Charisma. It also grows warm and throbs whenever its possessor comes within 20 feet of a mechanical or magic trap. (If the talisman is not held, its warning heat and pulses are of no avail.)</p><p>Regardless of which reaction results, a <i>talisman of reluctant wishes</i> disappears when its time period expires, leaving behind a 10,000 gp diamond in its stead.</p><p>Strong conjuration; CL 20th; Weight 1 lb.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1583,'Talisman of Ultimate Evil','Artifact','Minor Artifact','No','Strong evocation [evil]','18',NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Talisman of Ultimate Evil\" level=\"8\"><p><b>Talisman of Ultimate Evil:</b> An evil (LE, NE, CE) divine spellcaster who possesses this item can cause a flaming crack to open at the feet of a good (LG, NG, CG) divine spellcaster who is up to 100 feet away. The intended victim is swallowed up forever and sent hurtling to the center of the earth. The wielder of the talisman must be evil, and if she is not exceptionally foul and perverse in the sights of her evil deity the good character gains a DC 19 Reflex save to leap away from the crack. Obviously, the target must be standing on solid ground for this item to function.</p><p>A <i>talisman of ultimate evil</i> has 6 charges. If a neutral (LN, N, CN) divine spellcaster touches one of these stones, she takes 6d6 points of damage. If a good divine spellcaster touches one, she takes 8d6 points of damage. All other characters are unaffected by the device.</p><p>Strong evocation [evil]; CL 18th.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1584,'The Moaning Diamond','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Moaning Diamond\" level=\"8\"><p><b>The Moaning Diamond:</b> The <i>Moaning Diamond</i> appears to be an uncut diamond the size of a human fist. At all times, it gives forth a baleful moaning sound, as if in pain. Despite the noise, the <i>Moaning Diamond</i> is not evil. The wielder of the stone can, three times per day, call upon it to reshape earth and stone as if by the spell <i>stone shape</i>,  affecting 5,000 cubic feet of material. The <i>Moaning Diamond</i> can summon an elder earth elemental with maximum hit points that serves the caster until it is slain. Only one such elemental can be summoned at a time; if it is slain, a new creature cannot be summoned for 24 hours.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1585,'The Orbs of Dragonkind','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Orbs of Dragonkind\" level=\"8\"><p><b>The Orbs of Dragonkind:</b> Each of these fabled orbs contains the essence and personality of an ancient dragon of a different variety (one for each of the major ten different chromatic and metallic dragons). The bearer of an <i>Orb</i> can <i>dominate</i> dragons of its particular variety within 500 feet (as <i>dominate monster</i>), the dragon being forced to make a DC 25 Will save to resist. (Spell resistance is not useful against this effect.) Each <i>Orb of Dragonkind</i> bestows upon the wielder the AC and saving throw bonuses of the dragon within. These values replace whatever values the character would otherwise have, whether they are better or worse. These values cannot be modified by any means short of ridding the character of the <i>Orb</i>. A character possessing an <i>Orb of Dragonkind</i> is immune to the breath weapon-but only the breath weapon-of the dragon variety keyed to the <i>Orb</i>. Finally, a character possessing an <i>Orb</i> can herself use the breath weapon of the dragon in the <i>Orb</i> three times per day.</p><p>All <i>Orbs of Dragonkind</i> can be used to communicate verbally and visually with the possessors of the other <i>Orbs</i>. The owner of an <i>Orb</i> knows whether there are dragons within 10 miles at all times. For dragons of the <i>Orb</i>\'s particular variety, the range is 100 miles. If within 1 mile of a dragon of the <i>Orb</i>\'s variety, the wielder can determine the exact location and age of the creature. The bearer of one of these <i>Orbs</i> earns the enmity forever of all dragonkind for profiting by the enslavement of one of their kin, even if she later loses the item.</p><p>Each <i>Orb</i> also has an individual power that can be invoked once per round at 10th caster level.</p><ul>\n <li> <i>Black Dragon Orb: Fly</i> (Will DC 17 negates).</li>\n <li> <i>Blue Dragon Orb: Haste</i> (Fortitude DC 17 negates).</li>\n <li> <i>Brass Dragon Orb: Teleport</i> (Will DC 19 negates).</li>\n <li> <i>Bronze Dragon Orb: Scrying</i> (Will DC 18 negates).</li>\n <li> <i>Copper Dragon Orb: Suggestion</i> (Will DC 17 negates).</li>\n <li> <i>Gold Dragon Orb:</i> The owner of the gold <i>Orb</i> can call upon any power possessed by one of the other <i>Orbs</i>-including the <i>dominate</i> and breath weapon abilities but not AC, save bonuses, or breath weapon immunity-but can only use an individual</li>\n</ul><p>power once per day. She can use <i>dominate</i> on any other possessor of an <i>Orb</i> within 1 mile (Will DC 23 negates).</p><ul>\n <li> <i>Green Dragon Orb: Spectral hand</i>.</li>\n <li> <i>Red Dragon Orb: Wall of fire</i>.</li>\n <li> <i>Silver Dragon Orb: Cure critical wounds</i> (Will DC 18 half ).</li>\n <li> <i>White Dragon Orb: Protection from energy (cold)</i> (Fortitude DC 17 negates).</li>\n</ul><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1586,'The Saint\'s Mace','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Saint\'s Mace\" level=\"8\"><p><b>The Saint\'s Mace:</b> This relic appears to be a simple, well-used cudgel, but its simple appearance hides great power. The <i>saint\'s mace</i> has a +5 enhancement bonus and functions as a heavy mace with the holy, lawful, and disruption special abilities. The wielder can project <i>searing light</i> from the mace at will, at caster level 20th.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1587,'The Shadowstaff','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shadowstaff\" level=\"8\"><p><b>The Shadowstaff:</b> This artifact was crafted centuries ago, weaving together the wispy strands of shadow itself into a twisted black staff. The <i>Shadowstaff</i> makes the wielder slightly shadowy and incorporeal, granting him a +4 bonus to AC and Reflex saves (which stacks with any other bonuses). However, in bright light (such as that of the sun, but not a torch) or in absolute darkness, the wielder takes a -2 penalty on all attack rolls, saves, and checks.</p><p>The <i>Shadowstaff</i> also has these powers.</p><ul>\n <li> <i>Summon Shadows:</i> Three times per day the staff may summon 2d4 shadows. Immune to turning, they serve the wielder as if called by a <i>summon monster V</i> spell cast at 20th level.</li>\n <li> <i>Summon Nightshade:</i> Once per month, the staff can summon a nightcrawler nightshade that serves the wielder as if called by a <i>summon monster IX</i> spell cast at 20th level.</li>\n <li> <i>Shadow Form:</i> Three times per day the wielder can become a living shadow, with all the movement powers granted by the</li>\n</ul><p><i>gaseous form</i> spell.</p><ul>\n <li> <i>Shadow Bolt:</i> Three times per day the staff can project a ray attack that deals 10d6 points of cold damage to a single target. The shadow bolt has a range of 100 feet.</li>\n</ul><p/><p>The Shield of the Sun: This <i>+5 large shield</i>,  emblazoned with the symbol of the sun, allows the wielder to cast spells as if she were a 20th-level paladin with a Wisdom score of 20. The spells gained are cumulative with any existing spells per day that the character might have, even if she\'s already a paladin. The <i>Shield of the Sun</i> also grants spell resistance 15 to its wielder. It absorbs the first 10 points of damage from any energy attack (fire, cold, acid, electricity, or sonic). In return for all this, once per year the shield\'s owner must undertake a quest (no saving throw to avoid) at the behest of a lawful good deity.</p><p>A character who is evil or chaotic (LE, NE, CE, CN, CG) gains four negative levels if she attempts to use this artifact. Although these negative levels never results in actual level loss, they remain as long as the shield is in hand and cannot be overcome in any way (including <i>restoration</i> spells). The negative levels disappear when the shield is stowed or leaves the wearer\'s possession.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsVI');
INSERT INTO item VALUES (1588,'Aporter','Armor, Shield','Psionic','Yes','Moderate psychoportation',NULL,'+40,320 gp','10','Craft Psionic Arms and Armor, psionic dimension door',NULL,NULL,'\n      <div topic=\"Aporter\" level=\"8\"><p><b>Aporter:</b> As a standard action, a suit of aporter armor or an aporter shield transports the wearer and her equipment to any spot within 800 feet that she can visualize or specify, as the <i>psionic dimension door</i> power. The armor or shield can transport the wearer in this fashion twice per day.</p><p>Moderate psychoportation; ML 10th; Craft Psionic Arms and Armor, <i>psionic dimension door</i>; Price +40,320 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1589,'Averter','Shield','Psionic','Yes','Faint telepathy',NULL,'+12,960 gp','5','Craft Psionic Arms and Armor, aversion',NULL,NULL,'\n      <div topic=\"Averter\" level=\"8\"><p><b>Averter:</b> On command, up to three times per day, any creature to whom the wearer presents an averter shield must succeed on a DC 14 Will save or be overcome by a powerful aversion to the wielder (actually the shield), and will not approach within 30 feet. This is a mind-affecting compulsion effect, as the <i>aversion</i> power.</p><p>Faint telepathy; ML 5th; Craft Psionic Arms and Armor, <i>aversion</i>; Price +12,960 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1590,'Ectoplasmic','Armor','Psionic','Yes','Faint psychometabolism',NULL,'+10,800 gp','5','Craft Psionic Arms and Armor, ectoplasmic form',NULL,NULL,'\n      <div topic=\"Ectoplasmic\" level=\"8\"><p><b>Ectoplasmic:</b> As a standard action, ectoplasmic armor converts itself, its wearer, and all the wearer\'s equipment into <i>ectoplasmic form</i> for up to 5 minutes once per day, as the power of the same name. In this semisolid state, the wearer gains damage reduction 10/psionics.</p><p>Faint psychometabolism; ML 5th; Craft Psionic Arms and Armor, <i>ectoplasmic form</i>; Price +10,800 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1591,'Floating','Armor','Psionic','Yes','Faint psychoportation',NULL,'+4,000 gp','4','Craft Psionic Arms and Armor, float',NULL,NULL,'\n      <div topic=\"Floating\" level=\"8\"><p><b>Floating:</b> This kind of armor is psionically buoyant in water or a similar liquid, negating the normal penalty for wearing armor when making Swim checks. Additionally, it grants a +4 circumstance bonus on Swim checks.</p><p>Faint psychoportation; ML 4th; Craft Psionic Arms and Armor, <i>float</i>; Price +4,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1592,'Gleaming','Armor','Psionic','Yes','Faint metacreativity',NULL,'+3 bonus','5','Craft Psionic Arms and Armor, concealing amorpha',NULL,NULL,'\n      <div topic=\"Gleaming\" level=\"8\"><p><b>Gleaming:</b> This kind of armor is usually made of crystal, though it doesn\'t have to be. Gleams and flashes from the armor give the wearer and his armor a \'fuzzy\' appearance, granting the wearer concealment.</p><p>Faint metacreativity; ML 5th; Craft Psionic Arms and Armor, <i>concealing amorpha</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1593,'Heartening','Shield','Psionic','Yes','Faint psychometabolism',NULL,'+720 gp','4','Craft Psionic Arms and Armor, vigor',NULL,NULL,'\n      <div topic=\"Heartening\" level=\"8\"><p><b>Heartening:</b> This kind of shield grants the wearer up to 5 temporary hit points per day on command. These temporary hit points fade after 4 minutes. The wearer can activate this power as an immediate action at any time.</p><p>Faint psychometabolism; ML 4th; Craft Psionic Arms and Armor, <i>vigor</i>; Price +720 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1594,'Landing','Armor','Psionic','Yes','Faint psychoportation',NULL,'+4,000 gp','4','Craft Psionic Arms and Armor, catfall',NULL,NULL,'\n      <div topic=\"Landing\" level=\"8\"><p><b>Landing:</b> A suit of armor with this capability allows the wearer to ignore any damage dealt by the first 60 feet of a fall. Regardless of the height of a fall, the wearer always lands on her feet.</p><p>Faint psychoportation; ML 4th; Craft Psionic Arms and Armor, <i>catfall</i>; Price +4,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1595,'Linked','Armor, Shield','Psionic','Yes','Moderate telepathy',NULL,'+6,000 gp','6','Craft Psionic Arms and Armor, mindlink',NULL,NULL,'\n      <div topic=\"Linked\" level=\"8\"><p><b>Linked:</b> This kind of armor or shield allows the wearer to form a telepathic bond with other wearers of linked armor or shields within 10 miles. This ability is otherwise similar to the <i>mindlink</i> power.</p><p>Moderate telepathy; ML 6th; Craft Psionic Arms and Armor, <i>mindlink</i>; Price +6,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1596,'Manifester','Shield','Psionic','Yes','Moderate clairsentience',NULL,'+10,800 gp','6','Craft Psionic Arms and Armor, knowledge of any 2nd-level power',NULL,NULL,'\n      <div topic=\"Manifester\" level=\"8\"><p><b>Manifester:</b> This kind of shield generates 3 power points once per day that the wearer can use when manifesting a power he knows. These power points must all be used on the same power. As usual, a psionic character cannot pay a power\'s cost with power points from more than one source, so the power points in the shield must be used for discrete manifestations.</p><p>Moderate clairsentience; ML 6th; Craft Psionic Arms and Armor, knowledge of any 2nd-level power; Price +10,800 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1597,'Mindarmor','Armor, Shield','Psionic','Yes','Faint psychokinesis',NULL,'+24,000 gp','5','Craft Psionic Arms and Armor, empty mind',NULL,NULL,'\n      <div topic=\"Mindarmor\" level=\"8\"><p><b>Mindarmor:</b> This kind of armor or shield grants the wearer a +3 insight bonus on Will saving throws to resist all mind-affecting and/or compulsion powers.</p><p>Faint psychokinesis; ML 5th; Craft Psionic Arms and Armor, <i>empty mind</i>; Price +24,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
